//! `/reconnect` command: inspect and update stream reconnect settings.
//!
//! The command parses its arguments and forwards a `config/batchWrite` request to
//! the app server, which reloads the user config so the change applies from the
//! next turn. The widget only reports the resulting settings.

use super::*;
use crate::config_update::clear_config_value;
use crate::config_update::replace_config_value;
use codex_app_server_protocol::ConfigEdit;
use codex_config::config_toml::ReconnectConfigToml;
use codex_config::config_toml::ReconnectMode;
use serde_json::json;

/// Usage shown as the hint for `/reconnect` and as the error for unknown arguments.
pub(crate) const RECONNECT_USAGE: &str =
    "Usage: /reconnect [default | fixed <interval_ms> | retries <max_retries|default>]";

/// Arguments accepted by `/reconnect`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ReconnectCommand {
    /// Report the current settings.
    Show,
    /// Restore the built-in exponential backoff schedule.
    Default,
    /// Sleep for a constant interval on every reconnect attempt.
    Fixed(u64),
    /// Override the stream retry budget; `None` restores the provider default.
    Retries(Option<u64>),
}

impl ReconnectCommand {
    /// Config edits for a mutating command, or `None` when the command only reports settings.
    pub(crate) fn apply(
        self,
        current: ReconnectConfigToml,
    ) -> Option<(Vec<ConfigEdit>, ReconnectConfigToml, String)> {
        let (edits, applied) = match self {
            ReconnectCommand::Show => return None,
            ReconnectCommand::Default => (
                vec![
                    replace_config_value("reconnect.mode", json!("default")),
                    clear_config_value("reconnect.interval_ms"),
                ],
                ReconnectConfigToml {
                    mode: ReconnectMode::Default,
                    interval_ms: None,
                    max_retries: current.max_retries,
                },
            ),
            ReconnectCommand::Fixed(interval_ms) => (
                vec![
                    replace_config_value("reconnect.mode", json!("fixed")),
                    replace_config_value("reconnect.interval_ms", json!(interval_ms)),
                ],
                ReconnectConfigToml {
                    mode: ReconnectMode::Fixed,
                    interval_ms: Some(interval_ms),
                    max_retries: current.max_retries,
                },
            ),
            ReconnectCommand::Retries(max_retries) => {
                let edit = match max_retries {
                    Some(max_retries) => {
                        replace_config_value("reconnect.max_retries", json!(max_retries))
                    }
                    None => clear_config_value("reconnect.max_retries"),
                };
                (
                    vec![edit],
                    ReconnectConfigToml {
                        mode: current.mode,
                        interval_ms: current.interval_ms,
                        max_retries,
                    },
                )
            }
        };
        let summary = reconnect_update_summary(&applied);
        Some((edits, applied, summary))
    }
}

/// Parse the arguments typed after `/reconnect`.
pub(crate) fn parse_reconnect_args(args: &str) -> Result<ReconnectCommand, String> {
    let mut parts = args.split_whitespace();
    match (parts.next(), parts.next(), parts.next()) {
        (None, None, None) => Ok(ReconnectCommand::Show),
        (Some("default"), None, None) => Ok(ReconnectCommand::Default),
        (Some("fixed"), Some(interval_ms), None) => {
            let interval_ms: u64 = interval_ms.parse().map_err(|_| {
                format!(
                    "`fixed` expects an interval in milliseconds, e.g. /reconnect fixed 3000\n\
                     {RECONNECT_USAGE}"
                )
            })?;
            if interval_ms == 0 {
                return Err(format!(
                    "`fixed` requires an interval greater than zero\n{RECONNECT_USAGE}"
                ));
            }
            Ok(ReconnectCommand::Fixed(interval_ms))
        }
        (Some("retries"), Some("default"), None) => Ok(ReconnectCommand::Retries(None)),
        (Some("retries"), Some(max_retries), None) => {
            let max_retries: u64 = max_retries.parse().map_err(|_| {
                format!(
                    "`retries` expects a retry budget, e.g. /reconnect retries 5000\n\
                     {RECONNECT_USAGE}"
                )
            })?;
            if max_retries == 0 {
                return Err(format!(
                    "`retries` requires a budget greater than zero; use `retries default` to \
                     restore the provider default\n{RECONNECT_USAGE}"
                ));
            }
            Ok(ReconnectCommand::Retries(Some(max_retries)))
        }
        _ => Err(RECONNECT_USAGE.to_string()),
    }
}

/// Single-line description of the effective `[reconnect]` settings.
pub(crate) fn reconnect_status_summary(reconnect: &ReconnectConfigToml) -> String {
    let mode = match reconnect.mode {
        ReconnectMode::Default => "default (exponential backoff)".to_string(),
        ReconnectMode::Fixed => format!(
            "fixed every {}ms",
            reconnect.interval_ms.map_or_else(
                || "unset".to_string(),
                |interval_ms| interval_ms.to_string()
            )
        ),
    };
    let max_retries = reconnect.max_retries.map_or_else(
        || "provider default".to_string(),
        |max_retries| max_retries.to_string(),
    );
    format!("mode={mode}, max_retries={max_retries}")
}

/// Single-line confirmation shown after the settings were persisted.
pub(crate) fn reconnect_update_summary(reconnect: &ReconnectConfigToml) -> String {
    format!(
        "Reconnect settings updated: {}; applies from the next turn",
        reconnect_status_summary(reconnect)
    )
}

impl ChatWidget {
    /// Show the effective `[reconnect]` settings.
    pub(super) fn show_reconnect_status(&mut self) {
        let message = format!(
            "Reconnect settings: {}",
            reconnect_status_summary(&self.config.reconnect)
        );
        self.add_info_message(message, Some(RECONNECT_USAGE.to_string()));
    }

    /// Parse `/reconnect` arguments and, when they change settings, ask the app to persist them.
    pub(super) fn handle_reconnect_args(&mut self, args: &str) {
        let command = match parse_reconnect_args(args) {
            Ok(command) => command,
            Err(message) => {
                self.add_error_message(message);
                return;
            }
        };
        let Some((edits, applied, summary)) = command.apply(self.config.reconnect) else {
            self.show_reconnect_status();
            return;
        };
        self.app_event_tx.send(AppEvent::WriteReconnectConfig {
            edits,
            applied,
            summary,
        });
    }

    /// Keep the widget's config snapshot in sync after `/reconnect` persists new settings.
    pub(crate) fn apply_reconnect_config(&mut self, reconnect: ReconnectConfigToml) {
        self.config.reconnect = reconnect;
    }
}

use super::*;
use crate::chatwidget::reconnect_command::ReconnectCommand;
use crate::chatwidget::reconnect_command::parse_reconnect_args;
