use pretty_assertions::assert_eq;

#[test]
fn parse_reconnect_args_accepts_supported_forms() {
    assert_eq!(parse_reconnect_args(""), Ok(ReconnectCommand::Show));
    assert_eq!(parse_reconnect_args("  "), Ok(ReconnectCommand::Show));
    assert_eq!(
        parse_reconnect_args("default"),
        Ok(ReconnectCommand::Default)
    );
    assert_eq!(
        parse_reconnect_args("fixed 3000"),
        Ok(ReconnectCommand::Fixed(3000))
    );
    assert_eq!(
        parse_reconnect_args("retries 5000"),
        Ok(ReconnectCommand::Retries(Some(5000)))
    );
    assert_eq!(
        parse_reconnect_args("retries default"),
        Ok(ReconnectCommand::Retries(None))
    );
}

#[test]
fn parse_reconnect_args_rejects_invalid_forms() {
    for args in [
        "fast",
        "fixed",
        "fixed 0",
        "fixed soon",
        "retries 0",
        "retries many",
        "retries",
        "fixed 3000 5000",
        "default 3000",
    ] {
        let Err(message) = parse_reconnect_args(args) else {
            panic!("expected `{args}` to be rejected");
        };
        assert!(
            message.contains("Usage: /reconnect"),
            "expected usage in error for `{args}`, got: {message}"
        );
    }
}

#[test]
fn reconnect_status_summary_reports_effective_settings() {
    insta::assert_snapshot!(
        reconnect_status_summary(&ReconnectConfigToml::default()),
        @"mode=default (exponential backoff), max_retries=provider default"
    );
    insta::assert_snapshot!(
        reconnect_status_summary(&ReconnectConfigToml {
            mode: ReconnectMode::Fixed,
            interval_ms: Some(3000),
            max_retries: Some(10_000),
        }),
        @"mode=fixed every 3000ms, max_retries=10000"
    );
}

