#[tokio::test]
async fn reconnect_command_with_interval_persists_fixed_mode() {
    let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(/*model_override*/ None).await;

    chat.dispatch_command_with_args(
        SlashCommand::Reconnect,
        "fixed 3000".to_string(),
        Vec::new(),
    );

    let expected_edits = vec![
        crate::config_update::replace_config_value("reconnect.mode", serde_json::json!("fixed")),
        crate::config_update::replace_config_value(
            "reconnect.interval_ms",
            serde_json::json!(3000),
        ),
    ];
    let expected_applied = ReconnectConfigToml {
        mode: ReconnectMode::Fixed,
        interval_ms: Some(3000),
        max_retries: None,
    };
    let expected_summary = "Reconnect settings updated: mode=fixed every 3000ms, \
        max_retries=provider default; applies from the next turn"
        .to_string();
    match rx.try_recv() {
        Ok(AppEvent::WriteReconnectConfig {
            edits,
            applied,
            summary,
        }) => {
            pretty_assertions::assert_eq!(
                (edits, applied, summary),
                (expected_edits, expected_applied, expected_summary)
            );
        }
        other => panic!("expected reconnect config write, got {other:?}"),
    }
}

